description:
Write the chain follower from lesson 3.03 and use it on real objects:

```cpp
const void* followChain(const void* base, const std::vector<std::size_t>& offsets);
const int* healthByChain(const Game* game);
```

**followChain** starts at `base`. For every offset except the last, it reads the pointer stored at "current address + offset" and moves there; if that pointer is `nullptr` it returns `nullptr`. Finally it returns "current address + last offset" without reading. With no offsets it returns `base` itself. Read each stored pointer with `std::memcpy` from a byte address.

**healthByChain** finds the local player's health using only `followChain` and `offsetof`, starting from the `Game` object itself (not from a pointer to it):

```cpp
struct Stats  { int level; int health; int mana; };
struct Player { char name[16]; Stats* stats; };
struct World  { int tick; Player* players[8]; };
struct Game   { World* world; int localIndex; };
```

The local player is `world->players[localIndex]`. If anything along the way is missing it returns `nullptr`.

starter.solution.cpp:
#include <cstddef>
#include <vector>

struct Stats  { int level; int health; int mana; };
struct Player { char name[16]; Stats* stats; };
struct World  { int tick; Player* players[8]; };
struct Game   { World* world; int localIndex; };

const void* followChain(const void* base, const std::vector<std::size_t>& offsets) { return nullptr; }
const int* healthByChain(const Game* game) { return nullptr; }

solution.solution.cpp:
#include <cstddef>
#include <cstring>
#include <vector>

struct Stats  { int level; int health; int mana; };
struct Player { char name[16]; Stats* stats; };
struct World  { int tick; Player* players[8]; };
struct Game   { World* world; int localIndex; };

const void* followChain(const void* base, const std::vector<std::size_t>& offsets)
{
    const unsigned char* at{ static_cast<const unsigned char*>(base) };
    if (offsets.empty()) return at;
    for (std::size_t i{ 0 }; i + 1 < offsets.size(); ++i)
    {
        const void* next;
        std::memcpy(&next, at + offsets[i], sizeof(next));
        if (!next) return nullptr;
        at = static_cast<const unsigned char*>(next);
    }
    return at + offsets.back();
}

const int* healthByChain(const Game* game)
{
    const std::size_t slot{ offsetof(World, players) + sizeof(Player*) * static_cast<std::size_t>(game->localIndex) };
    return static_cast<const int*>(followChain(game, { offsetof(Game, world), slot, offsetof(Player, stats), offsetof(Stats, health) }));
}

unitTests:
TEST("a chain through real objects") {
    Stats stats{ 12, 87, 40 };
    Player hero{ "hero", &stats };
    Player other{ "other", nullptr };
    World world{ 500, { &other, &hero } };
    Game game{ &world, 1 };
    const int* health{ healthByChain(&game) };
    CHECK(health == &stats.health);
    stats.health = 55;
    CHECK_EQ(*healthByChain(&game), 55);
}
TEST("a broken link gives nullptr") {
    Player lonely{ "lonely", nullptr };
    World world{ 0, { &lonely } };
    Game game{ &world, 0 };
    CHECK(healthByChain(&game) == nullptr);
    game.localIndex = 3;
    CHECK(healthByChain(&game) == nullptr);
    Game noWorld{ nullptr, 0 };
    CHECK(healthByChain(&noWorld) == nullptr);
}
TEST("followChain by itself") {
    struct Inner { long long pad; int value; };
    struct Outer { int a; Inner* inner; };
    Inner inner{ 0, 42 };
    Outer outer{ 1, &inner };
    const void* found{ followChain(&outer, { offsetof(Outer, inner), offsetof(Inner, value) }) };
    CHECK(found == &inner.value);
    CHECK(followChain(&outer, {}) == &outer);
    CHECK(followChain(&outer, { offsetof(Outer, a) }) == &outer.a);
    Outer* const outerPtr{ &outer };
    CHECK(followChain(&outerPtr, { 0, offsetof(Outer, inner), offsetof(Inner, value) }) == &inner.value);
}

